import torch
import torch.nn as nn

from cutegen.ptx_runtime import PtxModule, i32, u32, i64, u64, f32, f64

KERNEL_NAME = "max_reduce_kernel"

PTX_SOURCE = r"""
.version 8.7
.target sm_89
.address_size 64
.visible .entry max_reduce_kernel(
    .param .u64 X_ptr,
    .param .u64 Y_ptr,
    .param .u64 outer_p,
    .param .u64 reduce_p,
    .param .u64 inner_p
)
{
    .reg .pred %p<29>;
    .reg .f32 %f<28>;
    .reg .b32 %r<8>;
    .reg .b64 %rd<98>;
    ld.param.u64 %rd1, [X_ptr];
    ld.param.u64 %rd2, [Y_ptr];
    ld.param.u64 %rd3, [outer_p];
    ld.param.u64 %rd4, [reduce_p];
    ld.param.u64 %rd5, [inner_p];
    cvta.to.global.u64 %rd1, %rd1;
    cvta.to.global.u64 %rd2, %rd2;
    // total = outer * inner (flattened output element count)
    mul.lo.s64 %rd6, %rd3, %rd5;
    // Each thread processes a contiguous group of up to 4 output
    // elements per grid-stride iteration. Because the inner dimension
    // is the fastest-varying / contiguous dimension of the input, four
    // consecutive output columns correspond to four consecutive,
    // 16-byte-aligned floats in global memory at every reduction step.
    // This lets us replace 4 scalar ld.global.f32 / st.global.f32 with
    // a single ld.global.v4.f32 / st.global.v4.f32, cutting the number
    // of memory instructions (and LSU issue pressure) by 4x for the
    // common case while preserving the same fully-coalesced access
    // pattern across the warp. A scalar fallback handles the tail
    // columns of each row (inner is not a multiple of 4) and any
    // partial group at the very end of the tensor.
    mov.u32 %r1, %ctaid.x;
    mov.u32 %r2, %ntid.x;
    mul.wide.u32 %rd7, %r1, %r2;
    mov.u32 %r3, %tid.x;
    cvt.u64.u32 %rd8, %r3;
    add.s64 %rd9, %rd7, %rd8;
    shl.b64 %rd9, %rd9, 2;            // idx0 = thread_linear_id * 4
    mov.u32 %r4, %nctaid.x;
    mul.wide.u32 %rd10, %r4, %r2;
    shl.b64 %rd10, %rd10, 2;          // stride = gridDim.x*blockDim.x*4
    // reduce_stride_bytes = inner * 4
    shl.b64 %rd26, %rd5, 2;
    // vec_limit = inner - 3, clamped to 0 when inner < 4 so the
    // vectorized path is never taken for degenerate shapes.
    sub.s64 %rd27, %rd5, 3;
    setp.lt.u64 %p0, %rd5, 4;
    selp.b64 %rd27, 0, %rd27, %p0;
    // NEW: disable vectorization entirely unless inner is a multiple of 4.
    // Without this, the per-reduction-step stride (inner*4 bytes) is not a
    // multiple of 16 bytes, so successive ld.global.v4.f32 addresses drift
    // out of 16-byte alignment even when the first load in the group is
    // aligned, causing a misaligned-address fault.
    and.b64  %rd60, %rd5, 3;
    setp.ne.u64 %p12, %rd60, 0;
    selp.b64 %rd27, 0, %rd27, %p12;
LOOP:
    setp.ge.u64 %p1, %rd9, %rd6;
    @%p1 bra DONE;
    // o = idx0 / inner ; rem = idx0 - o*inner
    div.u64 %rd11, %rd9, %rd5;
    mul.lo.s64 %rd12, %rd11, %rd5;
    sub.s64 %rd13, %rd9, %rd12;
    setp.lt.u64 %p2, %rd13, %rd27;
    @%p2 bra VEC_PATH;
    // ---- full-group fast path (common case when inner is not a multiple
    // of 4, so the 16-byte vectorized path above can never trigger): merge
    // the four per-column reduce-length loops into a single shared loop
    // that advances four independent addresses together. This removes the
    // redundant 4x replication of loop-control instructions (setp/branch/
    // increment) that a column-at-a-time scalar fallback would pay on every
    // reduction step, while keeping per-element scalar loads (safe for any
    // alignment) and a single fully-aligned vector store, since idx0 is
    // always a multiple of 4.
    add.s64 %rd70, %rd9, 3;
    setp.lt.u64 %p20, %rd70, %rd6;
    @%p20 bra FULL_GROUP;
    bra PARTIAL_GROUP;
FULL_GROUP:
    add.s64 %rd77, %rd13, 1;
    setp.ge.u64 %p21, %rd77, %rd5;
    sub.s64 %rd78, %rd77, %rd5;
    selp.b64 %rd71, %rd78, %rd77, %p21;
    selp.b64 %rd79, 1, 0, %p21;
    add.s64 %rd72, %rd11, %rd79;
    add.s64 %rd77, %rd71, 1;
    setp.ge.u64 %p22, %rd77, %rd5;
    sub.s64 %rd78, %rd77, %rd5;
    selp.b64 %rd73, %rd78, %rd77, %p22;
    selp.b64 %rd79, 1, 0, %p22;
    add.s64 %rd74, %rd72, %rd79;
    add.s64 %rd77, %rd73, 1;
    setp.ge.u64 %p23, %rd77, %rd5;
    sub.s64 %rd78, %rd77, %rd5;
    selp.b64 %rd75, %rd78, %rd77, %p23;
    selp.b64 %rd79, 1, 0, %p23;
    add.s64 %rd76, %rd74, %rd79;
    mul.lo.s64 %rd94, %rd11, %rd4;
    mul.lo.s64 %rd94, %rd94, %rd5;
    add.s64 %rd94, %rd94, %rd13;
    shl.b64 %rd94, %rd94, 2;
    add.s64 %rd90, %rd1, %rd94;
    mul.lo.s64 %rd94, %rd72, %rd4;
    mul.lo.s64 %rd94, %rd94, %rd5;
    add.s64 %rd94, %rd94, %rd71;
    shl.b64 %rd94, %rd94, 2;
    add.s64 %rd91, %rd1, %rd94;
    mul.lo.s64 %rd94, %rd74, %rd4;
    mul.lo.s64 %rd94, %rd94, %rd5;
    add.s64 %rd94, %rd94, %rd73;
    shl.b64 %rd94, %rd94, 2;
    add.s64 %rd92, %rd1, %rd94;
    mul.lo.s64 %rd94, %rd76, %rd4;
    mul.lo.s64 %rd94, %rd94, %rd5;
    add.s64 %rd94, %rd94, %rd75;
    shl.b64 %rd94, %rd94, 2;
    add.s64 %rd93, %rd1, %rd94;
    ld.global.f32 %f20, [%rd90];
    ld.global.f32 %f21, [%rd91];
    ld.global.f32 %f22, [%rd92];
    ld.global.f32 %f23, [%rd93];
    mov.u64 %rd95, 1;
FULL_INNER:
    setp.ge.u64 %p24, %rd95, %rd4;
    @%p24 bra FULL_STORE;
    add.s64 %rd90, %rd90, %rd26;
    add.s64 %rd91, %rd91, %rd26;
    add.s64 %rd92, %rd92, %rd26;
    add.s64 %rd93, %rd93, %rd26;
    ld.global.f32 %f24, [%rd90];
    ld.global.f32 %f25, [%rd91];
    ld.global.f32 %f26, [%rd92];
    ld.global.f32 %f27, [%rd93];
    setp.gt.f32 %p25, %f24, %f20;
    selp.f32 %f20, %f24, %f20, %p25;
    setp.gt.f32 %p26, %f25, %f21;
    selp.f32 %f21, %f25, %f21, %p26;
    setp.gt.f32 %p27, %f26, %f22;
    selp.f32 %f22, %f26, %f22, %p27;
    setp.gt.f32 %p28, %f27, %f23;
    selp.f32 %f23, %f27, %f23, %p28;
    add.s64 %rd95, %rd95, 1;
    bra FULL_INNER;
FULL_STORE:
    shl.b64 %rd96, %rd9, 2;
    add.s64 %rd97, %rd2, %rd96;
    st.global.v4.f32 [%rd97], {%f20, %f21, %f22, %f23};
    bra LOOP_NEXT;
PARTIAL_GROUP:
    mov.u64 %rd40, 0;
SCALAR_LOOP:
    setp.ge.u64 %p3, %rd40, 4;
    @%p3 bra SCALAR_DONE;
    add.s64 %rd41, %rd9, %rd40;
    setp.ge.u64 %p4, %rd41, %rd6;
    @%p4 bra SCALAR_NEXT;
    add.s64 %rd44, %rd13, %rd40;
    mov.u64 %rd42, %rd11;
WRAP1:
    setp.lt.u64 %p13, %rd44, %rd5;
    @%p13 bra WRAP_DONE;
    sub.s64 %rd44, %rd44, %rd5;
    add.s64 %rd42, %rd42, 1;
    bra WRAP1;
WRAP_DONE:
    mul.lo.s64 %rd45, %rd42, %rd4;
    mul.lo.s64 %rd46, %rd45, %rd5;
    add.s64 %rd47, %rd46, %rd44;
    shl.b64 %rd48, %rd47, 2;
    add.s64 %rd49, %rd1, %rd48;
    ld.global.f32 %f10, [%rd49];
    mov.u64 %rd50, 1;
    mov.u64 %rd51, %rd49;
SCALAR_INNER:
    setp.ge.u64 %p5, %rd50, %rd4;
    @%p5 bra SCALAR_STORE;
    add.s64 %rd51, %rd51, %rd26;
    ld.global.f32 %f11, [%rd51];
    setp.gt.f32 %p6, %f11, %f10;
    selp.f32 %f10, %f11, %f10, %p6;
    add.s64 %rd50, %rd50, 1;
    bra SCALAR_INNER;
SCALAR_STORE:
    shl.b64 %rd52, %rd41, 2;
    add.s64 %rd53, %rd2, %rd52;
    st.global.f32 [%rd53], %f10;
SCALAR_NEXT:
    add.s64 %rd40, %rd40, 1;
    bra SCALAR_LOOP;
SCALAR_DONE:
    bra LOOP_NEXT;
VEC_PATH:
    // base = o*reduce*inner + rem
    mul.lo.s64 %rd14, %rd11, %rd4;
    mul.lo.s64 %rd15, %rd14, %rd5;
    add.s64 %rd16, %rd15, %rd13;
    shl.b64 %rd17, %rd16, 2;
    add.s64 %rd18, %rd1, %rd17;
    ld.global.v4.f32 {%f1, %f2, %f3, %f4}, [%rd18];
    mov.u64 %rd19, 1;
    mov.u64 %rd23, %rd18;
VEC_INNER:
    setp.ge.u64 %p7, %rd19, %rd4;
    @%p7 bra VEC_STORE;
    add.s64 %rd23, %rd23, %rd26;
    ld.global.v4.f32 {%f5, %f6, %f7, %f8}, [%rd23];
    setp.gt.f32 %p8, %f5, %f1;
    selp.f32 %f1, %f5, %f1, %p8;
    setp.gt.f32 %p9, %f6, %f2;
    selp.f32 %f2, %f6, %f2, %p9;
    setp.gt.f32 %p10, %f7, %f3;
    selp.f32 %f3, %f7, %f3, %p10;
    setp.gt.f32 %p11, %f8, %f4;
    selp.f32 %f4, %f8, %f4, %p11;
    add.s64 %rd19, %rd19, 1;
    bra VEC_INNER;
VEC_STORE:
    shl.b64 %rd24, %rd9, 2;
    add.s64 %rd25, %rd2, %rd24;
    st.global.v4.f32 [%rd25], {%f1, %f2, %f3, %f4};
LOOP_NEXT:
    add.s64 %rd9, %rd9, %rd10;
    bra LOOP;
