"""

_module = None


def _get_module():
    global _module
    if _module is None:
        _module = PtxModule(PTX_SOURCE)
    return _module


def validate_generated_code():
    """Look up the kernel entry point to verify the PTX module is valid."""
    module = _get_module()
    fn = module.function(KERNEL_NAME)
    assert fn is not None, f"Kernel '{KERNEL_NAME}' not found in PTX module"
    return fn


class ModelNew(nn.Module):
    """
    Model that performs Max reduction over a specific dimension using a
    hand-authored PTX kernel launched via cutegen.ptx_runtime.PtxModule.

    Optimization applied: the kernel now uses a 1D grid-stride loop over the
    flattened (outer, inner) output index space instead of a fixed 2D grid
    tied 1:1 to the output shape. This lets the host launch a grid sized to
    a small number of full occupancy "waves" on the target GPU (avoiding a
    trailing partial wave / tail effect), while each thread cooperatively
    covers the remaining output elements via striding. This preserves
    identical reduction semantics while eliminating launch-configuration
    inefficiency flagged by profiling (partial-wave tail effect).
    """

    def __init__(self, dim: int):
        super(ModelNew, self).__init__()
        self.dim = dim
        self._module = _get_module()

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        assert x.is_cuda, "x must be a CUDA tensor"
        assert x.dtype == torch.float32, "x must be float32"

        x_c = x.contiguous()
        ndim = x_c.dim()
        dim = self.dim
        if dim < 0:
            dim += ndim
        assert 0 <= dim < ndim, "dim out of range"

        outer = 1
        for d in range(dim):
            outer *= x_c.size(d)
        reduce = x_c.size(dim)
        inner = 1
        for d in range(dim + 1, ndim):
            inner *= x_c.size(d)

        out_sizes = [x_c.size(d) for d in range(ndim) if d != dim]
        y = torch.empty(out_sizes, device=x_c.device, dtype=x_c.dtype)

        threads = 256
        total = outer * inner
        # One thread handles one output element per grid-stride iteration
        # (idx advances by exactly 1 element per thread). This ensures that
        # threads within a warp access consecutive output columns (and thus
        # consecutive/contiguous input addresses at each reduction step),
        # which is fully coalesced. The previous 4-columns-per-thread scheme
        # produced a stride-4 access pattern across the warp (since idx was
        # advanced in groups of 4 per thread), wasting a large fraction of
        # each fetched cache line despite reporting near-peak DRAM
        # throughput. Since inner (e.g. 4095) is frequently not divisible by
        # 4, the vectorized v4 path was effectively dead code for such
        # shapes anyway, so a scalar-but-coalesced mapping is strictly
        # better here.
        max_blocks = (total + threads - 1) // threads
        # Target GPU (RTX 4090, sm_89) has 128 SMs. Cap the grid at one full
        # wave (num_sm * blocks_per_sm) only when the actual required block
        # count exceeds it; the grid-stride loop inside the kernel still
        # covers any remaining output elements beyond the launched grid in
        # that case.
        num_sm = 128
        blocks_per_sm = 6
        grid_x = min(max_blocks, num_sm * blocks_per_sm)
        grid_x = max(grid_x, 1)

        stream = torch.cuda.current_stream()

        kernel_args = (
            u64(x_c.data_ptr()),
            u64(y.data_ptr()),
            u64(outer),
            u64(reduce),
            u64(inner),
        )
        self._module.launch(
            KERNEL_NAME,
            (int(grid_x), 1, 1),
            (int(threads), 1, 1),
            kernel_args,
            stream=stream,
        )

        return y

